// Ported from: scripts/i18n/content-translation-core.mjs, src/lib/content-packs.ts (key hashing, canonical JSON)
// Fixture generated by app/tool/i18n/export.mjs from scripts/i18n/catalog-fixtures.json + scripts/i18n/content/*.json.
import 'dart:convert';
import 'dart:io';

import 'package:anacan/core/content_packs/content_key.dart';
import 'package:anacan/core/i18n/js_compat.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  final fixture = jsonDecode(File('test/core/content_packs/fixtures/content_samples.json').readAsStringSync()) as Map<String, dynamic>;
  final golden = jsonDecode(File('test/core/i18n/fixtures/golden.json').readAsStringSync()) as Map<String, dynamic>;

  group('content translation keys (real public rows)', () {
    for (final sample in (fixture['rows'] as List).cast<Map<String, dynamic>>()) {
      final row = Map<String, dynamic>.from(sample['row'] as Map);
      for (final field in (sample['fields'] as List).cast<String>()) {
        test('${sample['table']}.$field matches the key present in the content packs', () {
          final expected = (sample['keys'] as Map)[field] as String;
          expect(contentTranslationKey(row, field), expected);
        });
      }
    }
  });

  group('canonicalisation edge cases (Node-computed)', () {
    for (final sample in (fixture['synthetic'] as List).cast<Map<String, dynamic>>()) {
      final row = Map<String, dynamic>.from(sample['row'] as Map);
      final field = sample['field'] as String;
      test('row ${row['id']} field $field', () {
        final value = [row[field], row['${field}_az'], row['${field}_en']];
        expect(canonicalContent(value), sample['canonical']);
        expect(canonicalJson(value), sample['canonicalCodeUnit']);
        expect(contentTranslationKey(row, field), sample['key']);
      });
    }
    test('rows without a string/number id have no key', () {
      expect(contentTranslationKey({'id': null, 'title': 'x'}, 'title'), isNull);
      expect(contentTranslationKey({'title': 'x'}, 'title'), isNull);
      expect(contentTranslationKey(null, 'title'), isNull);
    });
  });

  test("localeCompare(_, 'en') ordering of object keys matches ICU", () {
    final collation = golden['collation'] as Map<String, dynamic>;
    final input = (collation['input'] as List).cast<String>();
    final sorted = [...input]..sort(compareLocaleEn);
    expect(sorted, collation['sorted']);
  });

  test('JS number formatting used by JSON.stringify', () {
    expect(jsNumberToString(1e21), '1e+21');
    expect(jsNumberToString(1e-7), '1e-7');
    expect(jsNumberToString(1.5e-7), '1.5e-7');
    expect(jsNumberToString(0.000001), '0.000001');
    expect(jsNumberToString(100.0), '100');
    expect(jsNumberToString(-0.0), '0');
    expect(jsNumberToString(123456789012345680000.0), '123456789012345680000');
    expect(jsNumberToString(3.14159), '3.14159');
    expect(jsNumberToString(-42.5), '-42.5');
    expect(jsNumberToString(7.5), '7.5');
  });

  test('keyBucket routes by the first 8 hex digits of the key hash', () {
    const key = 'id-1:info:ffffffff00000000000000000000000000000000000000000000000000000000';
    expect(keyBucket(key, 1), 0);
    expect(keyBucket(key, 4), 0xffffffff % 4);
    expect(keyBucket('id:info:0000000a', 8), 2);
    expect(keyField('a:b:info:abc'), 'info');
  });
}
